CREATE TABLE IF NOT EXISTS organization (id TEXT PRIMARY KEY, name TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'Asia/Jakarta', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS app_user (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organization(id), auth_subject TEXT, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS area (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organization(id), name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customer_outlet (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organization(id), area_id TEXT REFERENCES area(id), external_code TEXT, name TEXT NOT NULL, address TEXT, latitude_e7 INTEGER, longitude_e7 INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customer_assignment (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organization(id), outlet_id TEXT NOT NULL REFERENCES customer_outlet(id), rep_id TEXT REFERENCES app_user(id), channel TEXT NOT NULL CHECK(channel IN ('field','telesales')), effective_from_date TEXT NOT NULL, effective_to_date TEXT);
CREATE TABLE IF NOT EXISTS invoice (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organization(id), source_invoice_id TEXT NOT NULL, source_version TEXT NOT NULL, outlet_id TEXT REFERENCES customer_outlet(id), rep_id TEXT REFERENCES app_user(id), area_id TEXT REFERENCES area(id), channel TEXT CHECK(channel IN ('field','telesales')), invoice_date TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'IDR', net_minor INTEGER NOT NULL CHECK(net_minor>=0), status TEXT NOT NULL CHECK(status IN ('validated','cancelled','draft')), validation_state TEXT NOT NULL DEFAULT 'provisional', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,source_invoice_id,source_version));
CREATE TABLE IF NOT EXISTS target_plan (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organization(id), name TEXT NOT NULL, method TEXT NOT NULL CHECK(method IN ('bottom_up','top_down')), period_start TEXT NOT NULL, period_end TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS target_item (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organization(id), target_plan_id TEXT NOT NULL REFERENCES target_plan(id), user_id TEXT REFERENCES app_user(id), outlet_id TEXT REFERENCES customer_outlet(id), target_minor INTEGER NOT NULL CHECK(target_minor>=0), baseline_kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS incentive_plan (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organization(id), name TEXT NOT NULL, role_code TEXT NOT NULL, channel TEXT NOT NULL, model TEXT NOT NULL, basis TEXT NOT NULL DEFAULT 'invoice_net', status TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS activity (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organization(id), outlet_id TEXT REFERENCES customer_outlet(id), user_id TEXT NOT NULL REFERENCES app_user(id), channel TEXT NOT NULL, activity_kind TEXT NOT NULL, status TEXT NOT NULL, occurred_at TEXT NOT NULL, notes TEXT);
CREATE INDEX IF NOT EXISTS idx_invoice_period ON invoice(organization_id,invoice_date,status);
CREATE INDEX IF NOT EXISTS idx_customer_assignment_active ON customer_assignment(organization_id,outlet_id,effective_from_date,effective_to_date);
CREATE INDEX IF NOT EXISTS idx_activity_user_time ON activity(organization_id,user_id,occurred_at);
